import React, { useState } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';

const Checkout = () => {
    const location = useLocation();
    const navigate = useNavigate();

    // Nhận dữ liệu từ trang Cart truyền sang (Đã có thêm couponCode)
    const { subtotal, shipping, discount, total, cartItems, couponCode } = location.state ||
        { subtotal: 0, shipping: 0, discount: 0, total: 0, cartItems: [], couponCode: null };

    const [formData, setFormData] = useState({
        firstName: '', lastName: '', address: '', town: '', phone: '', email: '', notes: ''
    });
    const [paymentMethod, setPaymentMethod] = useState('Cash On Delivery');

    const handleInputChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handlePlaceOrder = async (e) => {
        e.preventDefault();

        // Kiểm tra thông tin bắt buộc
        if (!formData.firstName || !formData.address || !formData.phone) {
            alert("Ní ơi điền đầy đủ Tên, Địa chỉ với Số điện thoại (có dấu *) giùm tui nha!");
            return;
        }

        const orderData = {
            userId: 'CUST-001', // Tạm thời fix cứng ID khách hàng
            shippingAddress: `${formData.address}, ${formData.town}`,
            phone: formData.phone,
            orderNotes: formData.notes,
            paymentMethod: paymentMethod,
            subTotal: subtotal,
            shippingFee: shipping,
            discountAmount: discount,
            totalAmount: total,
            couponCode: couponCode, // NÉM MÃ GIẢM GIÁ XUỐNG C# LƯU VÀO DB
            // Danh sách chi tiết để lưu vào bảng OrderDetails
            details: cartItems.map(item => ({
                productId: item.productId,
                quantity: item.quantity,
                unitPrice: item.productInfo?.price || item.price
            }))
        };

        try {
            const response = await fetch('http://localhost:5001/api/orders/checkout', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(orderData)
            });

            if (response.ok) {
                // Mở cửa sổ in hóa đơn của trình duyệt (để in bill)
                window.print();
                alert("🎉 Đặt hàng thành công! Hóa đơn đã được lưu vào Database.");
                // Đẩy khách về lại trang chủ
                navigate('/');
            } else {
                const errorData = await response.text();
                alert(`Có lỗi xảy ra: ${errorData}`);
            }
        } catch (error) {
            console.error("Lỗi kết nối API:", error);
            alert("Lỗi kết nối máy chủ C#!");
        }
    };

    return (
        <>
            {/* Header cho đẹp đội hình */}
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Checkout</h1>
                <ol className="breadcrumb justify-content-center mb-0">
                    <li className="breadcrumb-item"><Link to="/">Home</Link></li>
                    <li className="breadcrumb-item"><a href="#">Pages</a></li>
                    <li className="breadcrumb-item active text-white">Checkout</li>
                </ol>
            </div>

            <div className="container-fluid py-5">
                <div className="container py-5">
                    <h1 className="mb-4">Billing details</h1>
                    <form onSubmit={handlePlaceOrder}>
                        <div className="row g-5">
                            {/* CỘT BÊN TRÁI: THÔNG TIN KHÁCH HÀNG */}
                            <div className="col-md-12 col-lg-6 col-xl-7">
                                <div className="row">
                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100">
                                            <label className="form-label my-3">First Name<sup>*</sup></label>
                                            <input type="text" name="firstName" className="form-control" onChange={handleInputChange} required />
                                        </div>
                                    </div>
                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100">
                                            <label className="form-label my-3">Last Name</label>
                                            <input type="text" name="lastName" className="form-control" onChange={handleInputChange} />
                                        </div>
                                    </div>
                                </div>
                                <div className="form-item">
                                    <label className="form-label my-3">Address <sup>*</sup></label>
                                    <input type="text" name="address" className="form-control" placeholder="House Number Street Name" onChange={handleInputChange} required />
                                </div>
                                <div className="form-item">
                                    <label className="form-label my-3">Town/City<sup>*</sup></label>
                                    <input type="text" name="town" className="form-control" onChange={handleInputChange} required />
                                </div>
                                <div className="form-item">
                                    <label className="form-label my-3">Mobile<sup>*</sup></label>
                                    <input type="text" name="phone" className="form-control" onChange={handleInputChange} required />
                                </div>
                                <div className="form-item">
                                    <label className="form-label my-3">Email Address</label>
                                    <input type="email" name="email" className="form-control" onChange={handleInputChange} />
                                </div>
                                <hr />
                                <div className="form-item mt-3">
                                    <textarea name="notes" className="form-control" spellCheck="false" cols="30" rows="5" placeholder="Order Notes (Optional)" onChange={handleInputChange}></textarea>
                                </div>
                            </div>

                            {/* CỘT BÊN PHẢI: TÓM TẮT ĐƠN HÀNG */}
                            <div className="col-md-12 col-lg-6 col-xl-5">
                                <div className="table-responsive bg-light rounded p-5">
                                    <h2 className="display-6 mb-4">Cart Total</h2>
                                    <table className="table">
                                        <thead>
                                            <tr>
                                                <th scope="col">Products</th>
                                                <th scope="col">Name</th>
                                                <th scope="col">Price</th>
                                                <th scope="col">Qty</th>
                                                <th scope="col">Total</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {cartItems.map((item, index) => {
                                                const itemPrice = item.productInfo?.price || item.price;
                                                return (
                                                    <tr key={index}>
                                                        <th scope="row">
                                                            <div className="d-flex align-items-center mt-2">
                                                                <img src={item.productInfo?.imageUrl || item.imageUrl || '/img/avatar.jpg'} className="img-fluid rounded-circle" style={{ width: '60px', height: '60px' }} alt="" />
                                                            </div>
                                                        </th>
                                                        <td className="py-5">{item.productInfo?.name || item.name}</td>
                                                        <td className="py-5">${itemPrice.toFixed(2)}</td>
                                                        <td className="py-5">{item.quantity}</td>
                                                        <td className="py-5">${(itemPrice * item.quantity).toFixed(2)}</td>
                                                    </tr>
                                                );
                                            })}
                                            <tr>
                                                <th scope="row"></th>
                                                <td className="py-5"></td>
                                                <td className="py-5"></td>
                                                <td className="py-5"><p className="mb-0 text-dark py-3">Subtotal</p></td>
                                                <td className="py-5"><div className="py-3 border-bottom border-top"><p className="mb-0 text-dark">${subtotal.toFixed(2)}</p></div></td>
                                            </tr>
                                            <tr>
                                                <th scope="row"></th>
                                                <td className="py-5"><p className="mb-0 text-dark py-4">Shipping</p></td>
                                                <td colSpan="2" className="py-5"></td>
                                                <td className="py-5"><div className="py-4 border-bottom"><p className="mb-0 text-dark">${shipping.toFixed(2)}</p></div></td>
                                            </tr>
                                            {/* HIỂN THỊ MÃ GIẢM GIÁ NẾU CÓ */}
                                            {discount > 0 && (
                                                <tr>
                                                    <th scope="row"></th>
                                                    <td className="py-5"><p className="mb-0 text-success py-4">Discount ({couponCode})</p></td>
                                                    <td colSpan="2" className="py-5"></td>
                                                    <td className="py-5"><div className="py-4 border-bottom"><p className="mb-0 text-success">-${discount.toFixed(2)}</p></div></td>
                                                </tr>
                                            )}
                                            <tr>
                                                <th scope="row"></th>
                                                <td className="py-5"><p className="mb-0 text-dark text-uppercase py-3">TOTAL</p></td>
                                                <td colSpan="2" className="py-5"></td>
                                                <td className="py-5"><div className="py-3 border-bottom border-top"><p className="mb-0 text-dark fw-bold text-primary">${total.toFixed(2)}</p></div></td>
                                            </tr>
                                        </tbody>
                                    </table>

                                    {/* PHƯƠNG THỨC THANH TOÁN */}
                                    <div className="row g-4 text-center align-items-center justify-content-center border-bottom py-3">
                                        <div className="col-12">
                                            <div className="form-check text-start my-3">
                                                <input type="radio" className="form-check-input bg-primary border-0" id="Transfer-1" name="payment" value="Direct Bank Transfer" onChange={(e) => setPaymentMethod(e.target.value)} />
                                                <label className="form-check-label" htmlFor="Transfer-1">Direct Bank Transfer</label>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="row g-4 text-center align-items-center justify-content-center border-bottom py-3">
                                        <div className="col-12">
                                            <div className="form-check text-start my-3">
                                                <input type="radio" className="form-check-input bg-primary border-0" id="Delivery-1" name="payment" value="Cash On Delivery" defaultChecked onChange={(e) => setPaymentMethod(e.target.value)} />
                                                <label className="form-check-label" htmlFor="Delivery-1">Cash On Delivery</label>
                                            </div>
                                        </div>
                                    </div>

                                    {/* NÚT CHỐT ĐƠN */}
                                    <div className="row g-4 text-center align-items-center justify-content-center pt-4">
                                        <button type="submit" className="btn border-secondary py-3 px-4 text-uppercase w-100 text-primary">Place Order</button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </form>
                </div>
            </div>

            <a href="#" className="btn btn-primary border-3 border-primary rounded-circle back-to-top"><i className="fa fa-arrow-up"></i></a>
        </>
    );
};

export default Checkout;
